import { Suspense } from 'react';
import { getAllProducts } from '@/lib/db';
import { cacheLife, cacheTag, revalidateTag } from 'next/cache';

async function ProductListing() {
  'use cache';
  cacheTag('products');
  cacheLife('hours');

  const products = await getAllProducts();

  return (
    <ul className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {products.map((product) => (
        <li
          key={product.id}
          className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
        >
          <h3 className="font-semibold text-gray-900">{product.name}</h3>
          <p className="mt-1 text-sm text-gray-600">{product.description}</p>
          <p className="mt-2 font-medium text-gray-900">
            ${(product.price / 100).toFixed(2)}
          </p>
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  return (
    <div className="mx-auto max-w-4xl space-y-8 p-8">
      <h1 className="text-2xl font-bold text-gray-900">Product Listing</h1>

      <form
        action={async () => {
          'use server';
          revalidateTag('products', 'max');
        }}
        className="flex items-center gap-4"
      >
        <button
          type="submit"
          className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        >
          Refresh Products
        </button>
        <span className="text-sm text-gray-500">
          Invalidates the products cache to fetch fresh data on next visit
        </span>
      </form>

      <Suspense
        fallback={
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="h-32 animate-pulse rounded-lg border border-gray-200 bg-gray-100"
              />
            ))}
          </div>
        }
      >
        <ProductListing />
      </Suspense>
    </div>
  );
}

